/**
 * The unaffiliated state of the Guild Panel (GDD §8).
 *
 * Two ways off the bench: found a charter of your own — name, tag, motto and a
 * banner request with a live sigil preview — or browse the active register and
 * join an existing guild.
 *
 * Banner note: the picked colour and emblem are forwarded to
 * `IBackend.createGuild` as a `BannerRequest`. The registry has the last word —
 * it will reallocate anything that does not read as its own banner next to the
 * rest of the register — so the panel defaults to the mark that WILL be issued
 * and says plainly when the request was overridden.
 *
 * The palette here is `GUILD_COLORS`, which overlaps the colours the world
 * seeder hands to RIVAL banners; only entries that are also `BANNER_PRESETS`
 * survive `resolveBanner`. The onboarding gate (ui/screens/onboarding.ts) offers
 * presets only, which is the better surface — this one is kept as-is so the
 * existing guild panel is not redesigned underneath anybody.
 */
import type { IBackend } from '../../backend/IBackend';
import { GUILD } from '../../config/balance';
import { GUILD_COLORS } from '../../config/visual';
import { guildPower } from '../../game/guild/power';
import { guildTileCounts } from '../../game/world/season';
import type { GameState, Guild } from '../../game/types';
import {
  badge,
  button,
  emptyState,
  guildSigil,
  ICONS,
  panel,
  sectionHeader,
  toast,
} from '../components';
import { clear, cssHex, el, fmtNum, haptic, rgba } from '../dom';
import { runAction, type GuildTabView } from './rosterTab';

const EMBLEM_COUNT = 8;

/** Synthetic guild used purely to drive the sigil preview. */
function previewGuild(name: string, tag: string, motto: string, color: number, emblem: number): Guild {
  return {
    id: 'preview',
    name,
    tag,
    motto,
    color,
    leaderId: 'preview',
    memberIds: ['preview'],
    roles: { preview: 'leader' },
    diplomats: ['preview'],
    createdAt: 0,
    emblem,
  };
}

export function createGuildCreate(backend: IBackend): GuildTabView {
  const root = el('div', { class: 'gpane is-on' });

  // ── form state ────────────────────────────────────────────────────────────
  let color = GUILD_COLORS[0];
  let emblem = 0;
  let allocationLocked = false;

  const nameInput = el('input', {
    class: 'field__input',
    attrs: { type: 'text', maxlength: 28, placeholder: 'IRON COVENANT', autocomplete: 'off' },
  });
  const tagInput = el('input', {
    class: 'field__input',
    attrs: { type: 'text', maxlength: 5, placeholder: 'IRON', autocomplete: 'off', spellcheck: 'false' },
  });
  const mottoInput = el('input', {
    class: 'field__input',
    attrs: { type: 'text', maxlength: 64, placeholder: 'We hold what we take.', autocomplete: 'off' },
  });

  const sigilFrame = el('div', { class: 'gcpreview__frame' });
  const previewName = el('div', { class: 'gcpreview__name', text: 'UNNAMED CHARTER' });
  const previewMotto = el('div', { class: 'gcpreview__motto', text: 'no motto filed' });
  const previewTag = el('span', { class: 'ghead__tag', text: '——' });
  const preview = el(
    'div',
    { class: 'gcpreview' },
    sigilFrame,
    el(
      'div',
      { class: 'grow' },
      previewName,
      el('div', { class: 'ghead__tagline' }, previewTag),
      previewMotto,
    ),
  );

  const swatches: HTMLButtonElement[] = [];
  const emblems: HTMLButtonElement[] = [];
  const colorGrid = el('div', { class: 'gcgrid' });
  const emblemGrid = el('div', { class: 'gcgrid' });

  function repaint(): void {
    const name = nameInput.value.trim();
    const tag = tagInput.value.trim().toUpperCase();
    const motto = mottoInput.value.trim();

    previewName.textContent = name.length > 0 ? name.toUpperCase() : 'UNNAMED CHARTER';
    previewTag.textContent = tag.length > 0 ? tag : '——';
    previewMotto.textContent = motto.length > 0 ? motto : 'no motto filed';

    preview.style.setProperty('--band', cssHex(color));
    preview.style.setProperty('--band-soft', rgba(color, 0.22));
    previewTag.style.color = cssHex(color);
    previewTag.style.borderColor = cssHex(color);

    clear(sigilFrame);
    sigilFrame.appendChild(guildSigil(previewGuild(name, tag, motto, color, emblem), 62));

    for (let i = 0; i < swatches.length; i++) {
      swatches[i].classList.toggle('is-on', GUILD_COLORS[i] === color);
    }
    // Emblem thumbnails only need re-drawing when the banner colour moves.
    if (artColor !== color) {
      artColor = color;
      renderEmblemArt();
    }
    for (let i = 0; i < emblems.length; i++) {
      emblems[i].classList.toggle('is-on', i === emblem);
    }
  }

  let artColor = -1;

  for (const swatchColor of GUILD_COLORS) {
    const btn = el('button', {
      class: 'gcswatch',
      style: `--sw:${cssHex(swatchColor)}`,
      attrs: { type: 'button' },
      aria: { label: `banner colour ${cssHex(swatchColor)}` },
    });
    btn.appendChild(el('i'));
    btn.addEventListener('click', () => {
      color = swatchColor;
      allocationLocked = true;
      haptic(9);
      repaint();
    });
    swatches.push(btn);
    colorGrid.appendChild(btn);
  }

  for (let i = 0; i < EMBLEM_COUNT; i++) {
    const index = i;
    const btn = el('button', {
      class: 'gcemblem',
      attrs: { type: 'button' },
      aria: { label: `emblem ${index + 1}` },
    });
    btn.addEventListener('click', () => {
      emblem = index;
      allocationLocked = true;
      haptic(9);
      repaint();
    });
    emblems.push(btn);
    emblemGrid.appendChild(btn);
  }

  function renderEmblemArt(): void {
    for (let i = 0; i < emblems.length; i++) {
      clear(emblems[i]);
      emblems[i].appendChild(guildSigil(previewGuild('', '', '', color, i), 30));
    }
  }

  for (const input of [nameInput, tagInput, mottoInput]) {
    input.addEventListener('input', () => {
      if (input === tagInput) tagInput.value = tagInput.value.toUpperCase().replace(/[^A-Z0-9]/g, '');
      repaint();
    });
  }

  const registryNote = el('div', {
    class: 'mono dim-2',
    style: 'font-size:9px;line-height:1.6;letter-spacing:.05em;text-transform:uppercase',
    text: 'Banner request. The Admiralty registry issues the final mark when the charter is filed.',
  });

  const founding = el('div', { class: 'tfverdict', text: 'ENTER A NAME AND A TAG' });

  function validate(state: GameState | null): string | null {
    const name = nameInput.value.trim();
    const tag = tagInput.value.trim().toUpperCase();
    if (name.length < 2) return 'guild name too short';
    if (tag.length < 2 || tag.length > 5) return 'guild tag must be 2-5 characters';
    if (state) {
      const taken = Object.values(state.guilds).some(
        (g) => g.tag.toUpperCase() === tag || g.name.toLowerCase() === name.toLowerCase(),
      );
      if (taken) return 'that name or tag is already flying';
    }
    return null;
  }

  const foundBtn = button('FILE THE CHARTER', {
    variant: 'primary',
    wide: true,
    icon: ICONS.check,
    onClick: () => {
      const state = lastState;
      const problem = validate(state);
      if (problem) {
        toast({ title: 'REJECTED', body: problem, kind: 'bad' });
        return;
      }
      const requested = { color, emblem };
      void (async () => {
        const guildId = await runAction(
          'CHARTER FILED',
          backend.createGuild(
            nameInput.value.trim(),
            tagInput.value.trim().toUpperCase(),
            mottoInput.value.trim(),
            requested,
          ),
        );
        if (guildId === undefined) return;
        const issued = backend.getState().guilds[guildId];
        if (issued && (issued.color !== requested.color || issued.emblem !== requested.emblem)) {
          toast({
            title: 'BANNER ISSUED',
            body: 'The registry allocated a different mark to keep every banner distinct.',
            kind: 'info',
          });
        }
      })();
    },
  });

  const createPanel = panel(
    { title: 'FOUND A CHARTER', subtitle: 'raise your own banner', accent: 'var(--cyan)', holo: true },
    preview,
    el(
      'div',
      { class: 'field selectable' },
      el('span', { class: 'field__label', text: 'GUILD NAME' }),
      nameInput,
    ),
    el(
      'div',
      { class: 'field selectable' },
      el('span', { class: 'field__label', text: 'TAG · 2–5 CHARACTERS' }),
      tagInput,
    ),
    el(
      'div',
      { class: 'field selectable' },
      el('span', { class: 'field__label', text: 'MOTTO' }),
      mottoInput,
    ),
    sectionHeader('BANNER COLOUR'),
    colorGrid,
    sectionHeader('EMBLEM'),
    emblemGrid,
    registryNote,
    founding,
    foundBtn,
  );

  // ── register ──────────────────────────────────────────────────────────────
  const registerList = el('div', { class: 'col' });
  const registerPanel = panel(
    { title: 'ACTIVE REGISTER', subtitle: 'guilds currently holding ground', accent: 'var(--gold)' },
    registerList,
  );

  const scroll = el('div', { class: 'gscroll' }, createPanel, registerPanel);
  root.appendChild(scroll);

  let lastState: GameState | null = null;
  let registerKey = '';
  let allocationKey = -1;

  function renderRegister(state: GameState): void {
    const tiles = guildTileCounts(state);
    const guilds = Object.values(state.guilds).sort(
      (a, b) => (tiles[b.id] ?? 0) - (tiles[a.id] ?? 0) || a.name.localeCompare(b.name),
    );

    const next = guilds
      .map((g) => `${g.id}:${g.memberIds.length}:${tiles[g.id] ?? 0}`)
      .join('|');
    if (next === registerKey) return;
    registerKey = next;

    clear(registerList);
    if (guilds.length === 0) {
      registerList.appendChild(emptyState('◇', 'no guilds on the register yet'));
      return;
    }

    for (const guild of guilds) {
      const full = guild.memberIds.length >= GUILD.maxMembers;
      const power = guildPower(state, guild.id);
      const row = el('div', { class: 'gitem', style: `--band:${cssHex(guild.color)}` });

      const sig = el('div', { class: 'dir__sig' });
      sig.appendChild(guildSigil(guild, 34));
      row.appendChild(sig);

      const id = el('div', { class: 'gitem__id' });
      const nameRow = el('div', { class: 'row', style: 'gap:6px' });
      nameRow.appendChild(el('span', { class: 'gitem__name grow', text: guild.name }));
      nameRow.appendChild(
        el('span', {
          class: 'ghead__tag',
          style: `color:${cssHex(guild.color)};border-color:${cssHex(guild.color)}`,
          text: guild.tag,
        }),
      );
      id.appendChild(nameRow);
      if (guild.motto) id.appendChild(el('div', { class: 'gitem__motto', text: guild.motto }));
      id.appendChild(
        el(
          'div',
          { class: 'gitem__stats' },
          el('span', { text: `${guild.memberIds.length}/${GUILD.maxMembers} CMDR` }),
          el('span', { text: `${tiles[guild.id] ?? 0} TILES` }),
          el('span', { text: `${fmtNum(power.total)} PWR` }),
        ),
      );
      row.appendChild(id);

      if (full) {
        row.appendChild(badge('FULL', 'bad'));
      } else {
        row.appendChild(
          button('JOIN', {
            variant: 'ghost',
            small: true,
            onClick: () => {
              void runAction('ENLISTED', backend.joinGuild(guild.id));
            },
          }),
        );
      }
      registerList.appendChild(row);
    }
  }

  return {
    el: root,
    sync(state: GameState): void {
      lastState = state;

      // Default the banner request to the mark the registry will actually issue
      // for the next charter, until the founder touches the picker.
      const allocation = Object.keys(state.guilds).length;
      if (!allocationLocked && allocation !== allocationKey) {
        allocationKey = allocation;
        color = GUILD_COLORS[allocation % GUILD_COLORS.length];
        emblem = allocation % EMBLEM_COUNT;
        repaint();
      }

      const problem = validate(state);
      if (problem) {
        founding.className = 'tfverdict is-bad';
        founding.textContent = problem.toUpperCase();
        foundBtn.disabled = true;
      } else {
        founding.className = 'tfverdict is-ok';
        founding.textContent = 'CHARTER READY TO FILE';
        foundBtn.disabled = false;
      }

      renderRegister(state);
    },
    dispose(): void {
      lastState = null;
      registerKey = '';
      allocationKey = -1;
    },
  };
}
